  settings_search_idx_fda: 'macOS ha revocado el Acceso total al disco de Xenon. Ocurre en cada actualización, porque el permiso está ligado a la firma de la app. Mientras falte, Xenon no indexa tu carpeta de usuario: si lo hiciera, macOS pediría permiso para Escritorio, Documentos, Descargas, Fotos y Música en cada pasada. Vuelve a activarlo en Ajustes del Sistema → Privacidad y seguridad → Acceso total al disco: quita Xenon de la lista y añádela otra vez.',
