  ra_guide_open: 'Guía paso a paso',
  ra_guide_title: 'Configura el móvil, paso a paso',
  ra_guide_close: 'Cerrar la guía',
  ra_guide_sub: 'Los pasos 1 a 3 ponen el panel en el móvil estando en casa. El resto solo hace falta si lo quieres también fuera de casa.',
  ra_guide_group_home: 'En casa, con tu propia Wi-Fi',
  ra_guide_group_away: 'Fuera de casa (opcional)',
  ra_guide_ack: 'Hecho',
  ra_guide_undo: 'Todavía no',
  ra_guide_s1: 'Activa el acceso desde otros dispositivos',
  ra_guide_s1_body: 'Está apagado hasta que lo enciendes tú. Mientras está apagado, Xenon responde a este PC y a nada más.',
  ra_guide_s2: 'Apunta el móvil al código QR',
  ra_guide_s2_body: 'El código es una invitación, no una contraseña: dura tres minutos y deja de servir tras unos pocos intentos fallidos. El panel se abre en el navegador del móvil. No hay nada que instalar en el móvil.',
  ra_guide_s2_wait: 'Disponible cuando el interruptor de arriba esté encendido.',
  ra_guide_s3: 'Añádelo a la pantalla de inicio del móvil',
  ra_guide_s3_body: 'En iPhone pulsa Compartir y luego Añadir a pantalla de inicio. En Android, Chrome te ofrece instalarlo. A partir de ahí Xenon se abre con su propio icono, a pantalla completa, y ahí funcionan el micrófono y las notificaciones.',
  ra_guide_s4: 'Activa la dirección segura',
  ra_guide_s4_body: 'Le da a este PC un nombre propio que funciona desde cualquier sitio, sobre una conexión cifrada. Usa Tailscale, que es gratis, y Xenon lo instala e inicia sesión por ti. No estás creando ninguna cuenta con Xenon.',
  ra_guide_s5: 'Activa los certificados HTTPS en tu cuenta de Tailscale',
  ra_guide_s5_body: 'Es el único paso que Xenon no puede hacer por ti. Abre la consola de administración de Tailscale, baja hasta HTTPS Certificates y pulsa Enable. Es gratis en todos los planes. Luego vuelve aquí: Xenon ha seguido esperando.',
  ra_guide_s6: 'Instala Tailscale en el móvil, con la misma cuenta',
  ra_guide_s6_body: 'Descárgalo de la App Store o Google Play, inicia sesión con la misma cuenta que acabas de usar y enciende su interruptor. Es el paso que todo el mundo olvida. Cuando falta, el móvil dice que no puede abrir la dirección: no está roto, esa dirección solo existe dentro de tu propia red.',
  ra_guide_s7: 'Empareja el móvil otra vez en la nueva dirección',
  ra_guide_s7_body: 'Pulsa Añadir dispositivo en el paso 2 y escanea de nuevo. El navegador ata el emparejamiento a la dirección en la que se hizo, así que un móvil emparejado en la dirección de casa no lo está en la segura. A partir de ahí solo necesitas la nueva, en casa y fuera.',
  ra_guide_done_title: 'La configuración está lista',
  ra_guide_done_body: 'El móvil está emparejado. Última cosa: ¿Xenon debe seguir abriéndose también en este PC?',
  ra_guide_keep: 'Que siga aquí también',
  ra_guide_hide: 'Ocultar Xenon en este PC',
  ra_guide_hide_note: 'Al ocultarlo, Xenon deja de abrirse en este PC, también al iniciar sesión. Sigue funcionando en segundo plano, así que el móvil sigue igual. Puedes recuperar la ventana desde el icono de Xenon junto al reloj, o desde Ajustes y luego Pantalla.',
  ra_guide_hide_browser: 'Esto es el panel dentro de un navegador, así que no hay ventana que ocultar. En la app de Xenon también puedes elegir que deje de abrirse en este PC.',
  settings_stack: 'Disposición de los paneles',
  settings_stack_auto: 'Automática',
  settings_stack_on: 'En una columna',
  settings_stack_off: 'En cuadrícula',
  settings_stack_note: 'Automática se adapta a la pantalla: una pantalla vertical tiene su propia disposición. En una columna apila los paneles, En cuadrícula mantiene la cuadrícula horizontal.',
  settings_supporter_title: 'Código de mecenas',
  settings_supporter_lead: 'Guárdalo aquí y no tendrás que pegarlo nunca más: los drops de mecenas se desbloquean con un toque. Se queda en este PC y nunca se envía a tus otras pantallas.',
  settings_supporter_save: 'Guardar',
  settings_supporter_forget: 'Quitar',
  settings_supporter_saved: 'Se queda en este PC y se usa solo cuando desbloqueas un drop.',
